package com.cpf.starter.tcp;import java.io.*;import java.net.*;import java.util.concurrent.*;import java.util.function.Function;import javax.net.ServerSocketFactory;import javax.net.ssl.*;
public final class CpfTcpServer implements AutoCloseable {private final CpfTcpProperties p;private final CpfTcpFrameCodec codec;private final Function<byte[],byte[]> handler;private final ExecutorService workers;private volatile boolean running;private ServerSocket server;private final CpfTcpTlsContextProvider tls;
 public CpfTcpServer(CpfTcpProperties p,Function<byte[],byte[]> h,CpfTcpTlsContextProvider tls){this.p=p;codec=new CpfTcpFrameCodec(p);handler=h;this.tls=tls;workers=Executors.newFixedThreadPool(p.getPoolSize(),Thread.ofVirtual().factory());}
 public synchronized void start(){if(running)return;try{ServerSocketFactory f=p.isTls()?tls.current().getServerSocketFactory():ServerSocketFactory.getDefault();server=f.createServerSocket(p.getPort());if(server instanceof SSLServerSocket ssl)ssl.setNeedClientAuth(p.isMutualTls());running=true;Thread.ofVirtual().name("cpf-tcp-accept").start(this::acceptLoop);}catch(IOException ex){throw new IllegalStateException("TCP server start failed",ex);}}
 private void acceptLoop(){while(running)try{Socket s=server.accept();workers.submit(()->handle(s));}catch(IOException ex){if(running)throw new IllegalStateException(ex);}}
 private void handle(Socket s){try(s){s.setSoTimeout((int)p.getIdleTimeout().toMillis());while(running&&!s.isClosed()){byte[] request=codec.read(s.getInputStream());byte[] response=handler.apply(request);if(response!=null)codec.write(s.getOutputStream(),response);}}catch(EOFException|SocketTimeoutException ignored){}catch(IOException ex){throw new UncheckedIOException(ex);}}
 public synchronized void close(){running=false;if(server!=null)try{server.close();}catch(IOException ignored){}workers.shutdown();try{workers.awaitTermination(Math.max(1,p.getResponseTimeout().toMillis()),TimeUnit.MILLISECONDS);}catch(InterruptedException ex){Thread.currentThread().interrupt();workers.shutdownNow();}}}
